#[derive(PartialEq, Eq, Clone, Debug)]
pub struct ListNode {
    pub val: i32,
    pub next: Option<Box<ListNode>>,
}

impl ListNode {
    #[inline]
    #[allow(dead_code)]
    pub fn new(val: i32) -> Self {
        ListNode { next: None, val }
    }
}

pub struct Solution;

impl Solution {
    pub fn remove_nth_from_end(head: Option<Box<ListNode>>, n: i32) -> Option<Box<ListNode>> {
        let mut sz = 0;
        let mut curr = head.as_ref();
        while let Some(node) = curr {
            sz += 1;
            curr = node.next.as_ref();
        }

        let mut dummy = Box::new(ListNode { val: 0, next: head });
        let steps_to_predecessor = sz - n;
        let mut curr_mut = &mut dummy;

        for _ in 0..steps_to_predecessor {
            curr_mut = curr_mut.next.as_mut().unwrap();
        }

        curr_mut.next = curr_mut.next.take().and_then(|node| node.next);

        dummy.next
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn to_list(vals: &[i32]) -> Option<Box<ListNode>> {
        let mut head = None;
        for &v in vals.iter().rev() {
            let mut node = Box::new(ListNode::new(v));
            node.next = head;
            head = Some(node);
        }
        head
    }

    fn to_vec(mut head: Option<Box<ListNode>>) -> Vec<i32> {
        let mut res = Vec::new();
        while let Some(node) = head {
            res.push(node.val);
            head = node.next;
        }
        res
    }

    #[test]
    fn test_example_1() {
        let head = to_list(&[1, 2, 3, 4, 5]);
        let res = Solution::remove_nth_from_end(head, 2);
        assert_eq!(to_vec(res), vec![1, 2, 3, 5]);
    }

    #[test]
    fn test_example_2() {
        let head = to_list(&[1]);
        let res = Solution::remove_nth_from_end(head, 1);
        assert_eq!(to_vec(res), Vec::<i32>::new());
    }

    #[test]
    fn test_example_3() {
        let head = to_list(&[1, 2]);
        let res = Solution::remove_nth_from_end(head, 1);
        assert_eq!(to_vec(res), vec![1]);
    }

    #[test]
    fn test_remove_head() {
        let head = to_list(&[1, 2, 3]);
        let res = Solution::remove_nth_from_end(head, 3);
        assert_eq!(to_vec(res), vec![2, 3]);
    }

    #[test]
    fn test_remove_tail() {
        let head = to_list(&[1, 2, 3]);
        let res = Solution::remove_nth_from_end(head, 1);
        assert_eq!(to_vec(res), vec![1, 2]);
    }
}
